`timescale 1ns / 100ps

module tb_TX_RX_Loopback;

    // ----------------------------------------------
    // Clock and reset
    // ----------------------------------------------
    reg         Tq;
    reg         rst;
    reg         srst;
    
    // Bit timing signals (generated by mod‑7 counter)
    reg         TXen;
    reg         RXen;
    
    // Bus signals
    wire        TX;
    wire        AckTakeOver;
    
    // Force condition: when TX is at EOF (state 9) and Cnt == 0
    wire        force_bus_dominant;
    assign      force_bus_dominant = (u_TX.TXSTATES == 4 && u_TX.Cnt == 26);
    
    // Bus signal with forced dominant at the last bit of EOF
    wire        bus;
    assign      bus = force_bus_dominant ? 1'b1 : (TX & AckTakeOver);
    
    // ----------------------------------------------
    // Instantiate TXMachine
    // ----------------------------------------------
    reg         Transmit;
    wire [3:0]  RXSTATES,TXSTATES;
    reg  [28:0] ID;
    reg         IDE;
    reg         RTR;
    reg  [63:0] data;
    reg  [3:0]  D_Len;
    reg  [8:0]  REC;
    reg  [8:0]  TEC;
    reg         ErrState;
    wire        tx_done;
    wire        req_Error_TX;
    wire doneforEH;
    wire IMTX;
    TXMachine u_TX (
        .rst         (rst),
        .srst        (srst),
        .Tq          (Tq),
        .Sampled_din (bus),
        .Transmit    (Transmit),
        .RXSTATES    (RXSTATES),
        .TXSTATES (TXSTATES),
        .TXen        (TXen),
        .ID          (ID),
        .IDE         (IDE),
        .RTR         (RTR),
        .data        (data),
        .D_Len       (D_Len),
        .REC         (REC),
        .TEC         (TEC),
        .ErrState    (ErrState),
        .TX          (TX),
        .req_Error   (req_Error_TX),
        .done        (tx_done),
        .imTX(imTX)
    );
    
    // ----------------------------------------------
    // Instantiate RXMachine
    // ----------------------------------------------
    wire        rx_done;
    wire [63:0] TOFILTERd;
    wire [28:0] TOFILTERI;
    wire [3:0]  D_Len_RX;
    wire        req_Error_RX;
    wire        IDE_RX;
    wire        RTR_RX;
    wire [3:0]  RXSTATES_RX;
    
    RXMachine u_RX (
        .Tq          (Tq),
        .rst         (rst),
        .srst        (srst),
        .TOFILTERd   (TOFILTERd),
        .TOFILTERI   (TOFILTERI),
        .RXBUS       (bus),
        .D_Len       (D_Len_RX),
        .req_Error   (req_Error_RX),
        .IDE         (IDE_RX),
        .AckTakeOver (AckTakeOver),
        .RXen        (RXen),
        .RTR         (RTR_RX),
        .ErrState    (1'b0),
        .OvlState    (1'b0),
        .RXSTATES    (RXSTATES_RX),
        .done        (rx_done),
        .TXen        (TXen),
        .imTX        (imTX)
    );
    
    // Connect receiver's RXSTATES to transmitter's RXSTATES input
    assign RXSTATES = RXSTATES_RX;
    
    // ----------------------------------------------
    // Clock generation (100 MHz Tq)
    // ----------------------------------------------
    always #5 Tq = ~Tq;
    
    // ----------------------------------------------
    // Bit timing: mod‑7 counter, TXen at 0, RXen at 5
    // ----------------------------------------------
    reg [2:0] bit_cnt;
    always @(posedge Tq or negedge rst) begin
        if (!rst) begin
            bit_cnt <= 0;
            TXen    <= 0;
            RXen    <= 0;
        end else begin
            bit_cnt <= (bit_cnt == 6) ? 0 : bit_cnt + 1;
            TXen    <= (bit_cnt == 0);
            RXen    <= (bit_cnt == 5);
        end
    end
    
    // ----------------------------------------------
    // Stimulus
    // ----------------------------------------------
    initial begin
        // Initialize inputs
        rst = 0;
        srst = 0;
        Tq = 0;
        Transmit = 0;
        ID = 29'b10101010101010101010101010000;
        IDE = 1;
        RTR = 0;
        data = 64'h4655434B4F464621;          // "FUCKYOU!"
        D_Len = 4'd8;
        REC = 8'd0;
        TEC = 8'd0;
        ErrState = 1'b0;
        
        // Apply reset
        #20 rst = 1;
        #20 srst = 1;
        
        // Wait for bus idle
        @(posedge Tq);
        @(posedge Tq);
        
        // Start transmission
        Transmit = 1;
        
        // Wait long enough for the frame to complete
        // The forced dominant at EOF will cause an error
        repeat (1900) @(posedge Tq);
        
        // Wait a few more cycles for receiver to finish
        repeat (20) @(posedge Tq);
        
        $finish;
    end
    
    // ----------------------------------------------
    // Monitor
    // ----------------------------------------------
    initial begin
        $monitor("Time=%t, TXen=%b, RXen=%b, AckTakeOver=%b, bus=%b, force=%b, RXSTATES=%d, TXSTATES=%d, RTR=%b, IDE=%b, D_Len=%d, DATA=%d, RX_Cnt=%d, RX_CRC=%d, TX_CRC=%d, ID=%d, reqrx=%b, reqtx=%b, donerx=%b, donetx=%b, imTX=%b",
                 $time, TXen, RXen, AckTakeOver, bus, force_bus_dominant, RXSTATES_RX, TXSTATES, RTR_RX, IDE_RX, D_Len_RX, TOFILTERd, u_RX.Cnt, u_RX.out_CRC, u_TX.out_CRC, TOFILTERI, req_Error_RX, req_Error_TX, rx_done, tx_done,imTX);
    end

endmodule